create table order_details (order_id integer, price numeric(15,2), quantity integer, total_price numeric(15,2), id bigint generated by default as identity, product_id bigint, product_name varchar(255), primary key (id));
create table product_review (customer_id integer, id integer generated by default as identity, rating integer, date timestamp(6), product_id bigint, comment varchar(255), primary key (id));
create table tbladmin (added_date timestamp(6), id bigint generated by default as identity, email varchar(255) not null unique, name varchar(255), password varchar(255), primary key (id));
create table tblcart (discount_price numeric(15,2), mrp_price numeric(15,2), quantity integer, total_price numeric(15,2), customer_id bigint, id bigint generated by default as identity, product_id bigint, primary key (id));
create table tblcustomer (id integer generated by default as identity, added_date timestamp(6), address varchar(255), email varchar(255) not null unique, gender varchar(255), name varchar(255), password varchar(255), phone varchar(255), pin_code varchar(255), primary key (id));
create table tblorders (id integer generated by default as identity, order_no integer, payment_id integer, product_price numeric(15,2), product_selling_price numeric(15,2), product_total_price numeric(15,2), quantity integer, order_date timestamp(6), address varchar(255), address_type varchar(255), customer_name varchar(255), email_id varchar(255), image varchar(255), mobile_number varchar(255), order_status varchar(255) check (order_status in ('PENDING','WAITING_FOR_PAYMENT','PROCESSING','SHIPPED','DELIVERED','CANCELLED')), payment_mode varchar(255) check (payment_mode in ('COD','VIETQR','MOMO','BANKING')), payment_status varchar(255) check (payment_status in ('PAID','UNPAID','REFUNDED')), pincode varchar(255), product_name varchar(255), transaction_id varchar(255), primary key (id));
create table tblproduct (discount_limit integer, discount_price numeric(15,2), discount_sold integer, mrp_price numeric(15,2), price numeric(15,2), stock integer, create_date timestamp(6), id bigint generated by default as identity, image varchar(1000), active varchar(255), code varchar(255), description TEXT, image_name varchar(255), name varchar(255), product_category varchar(255), primary key (id));
create table tblproduct_image (id bigint generated by default as identity, product_id bigint, image_name varchar(255), primary key (id));
alter table if exists order_details add constraint FKtpfyy8e09xdxyl57gonjib6f9 foreign key (order_id) references tblorders;
alter table if exists order_details add constraint FKtel4h7v40ohsj0xrrb2dmnf0k foreign key (product_id) references tblproduct;
alter table if exists product_review add constraint FK9ot380k45qo9n1cc3i9kjnmcr foreign key (customer_id) references tblcustomer;
alter table if exists product_review add constraint FK8awdas2tfkejwit6eveuphhpt foreign key (product_id) references tblproduct;
alter table if exists tblcart add constraint FKdd4v3miwrdosjwlk4e22bftd5 foreign key (product_id) references tblproduct;
alter table if exists tblproduct_image add constraint FKcdhohowu3ar0wxckbte535r94 foreign key (product_id) references tblproduct;
